#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    long long k; cin >> k;
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << (a[i] % k);
    }
    cout << "\n";
    return 0;
}
